import unicodedata


def slugify(s):
    # Lowercase
    s = s.lower()

    # Transliterate Unicode characters to ASCII
    s = unicodedata.normalize("NFKD", s)
    s = s.encode("ascii", "ignore").decode("ascii")

    # Build slug: alnum chars kept, non-alnum replaced with '-'
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append("-")

    # Collapse consecutive hyphens into one
    result = []
    for ch in out:
        if ch == "-" and result and result[-1] == "-":
            continue
        result.append(ch)

    # Strip leading/trailing hyphens
    return "".join(result).strip("-")

import unicodedata


def slugify(s):
    # Normalize unicode diacritics (e.g., õ -> o, ñ -> n)
    s = unicodedata.normalize("NFKD", s)
    s = "".join(c for c in s if not unicodedata.combining(c))

    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif ch in (" ", "-", "_", "\t"):
            out.append("-")
        # other characters (punctuation, etc.) are dropped

    # Collapse runs of consecutive hyphens into a single hyphen
    collapsed = []
    for ch in out:
        if ch == "-" and collapsed and collapsed[-1] == "-":
            continue
        collapsed.append(ch)

    # Strip any leading or trailing hyphens
    return "".join(collapsed).strip("-")

